import java.util.Scanner;

public class Main {
    static final int N = 500;
    static int md;
    static int[][] ch = new int[N + 1][N + 1];
    static Pair[] dp1 = new Pair[N + 1];
    static Pair[][][] dp2 = new Pair[2][N + 1][N + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void ad(long[] x, long y) {
        x[0] += y;
        if (x[0] >= md) x[0] -= md;
    }

    static long sm(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        md = sc.nextInt();

        for (int i = 0; i <= m; i++) {
            ch[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                ch[i][j] = ch[i - 1][j] + ch[i - 1][j - 1];
                if (ch[i][j] >= md) ch[i][j] -= md;
            }
        }

        for (int i = 0; i <= m; i++) {
            dp1[i] = new Pair();
        }
        dp1[0].first = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long w = (dp1[j - 1].first * dp1[i - j].first) % md;
                w = (w * ch[i - 1][j - 1]) % md;

                long[] secondVal = {dp1[i].second};
                long addVal1 = ((sm(j - 1) + sm(i - j)) % md) * w % md;
                ad(secondVal, addVal1);

                long addVal2 = (dp1[j - 1].second * dp1[i - j].first) % md;
                addVal2 = (addVal2 * (i + 1)) % md;
                addVal2 = (addVal2 * ch[i - 1][j - 1]) % md;
                ad(secondVal, addVal2);

                long addVal3 = (dp1[j - 1].first * dp1[i - j].second) % md;
                addVal3 = (addVal3 * (i + 1)) % md;
                addVal3 = (addVal3 * ch[i - 1][j - 1]) % md;
                ad(secondVal, addVal3);

                long[] firstVal = {dp1[i].first};
                long addVal4 = (w * (i + 1)) % md;
                ad(firstVal, addVal4);

                dp1[i].first = firstVal[0];
                dp1[i].second = secondVal[0];
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int ln = 1; ln <= n - i; ln++) {
                    if (dp2[0][i][j] == null) dp2[0][i][j] = new Pair();
                    if (dp2[1][i][j] == null) dp2[1][i][j] = new Pair();
                }
            }
        }

        dp2[0][0][0].first = 1;
        dp2[1][0][0].first = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                for (int ln = 1; ln <= n - i; ln++) {
                    // Update dp2[1][i + ln][j]
                    if (dp2[0][i][j] != null && dp2[1][i][j] != null) {
                        ad(new long[]{dp2[1][i + ln][j].first}, dp2[0][i][j].first);
                        ad(new long[]{dp2[1][i + ln][j].second}, dp2[0][i][j].second);
                    }

                    // Update dp2[0][i + ln][j + ln]
                    if (dp2[1][i][j] != null) {
                        long val1 = (dp2[1][i][j].first * dp1[ln].first) % md;
                        val1 = (val1 * ch[j + ln][j]) % md;
                        ad(new long[]{dp2[0][i + ln][j + ln].first}, val1);

                        long val2 = (dp2[1][i][j].first * dp1[ln].second) % md;
                        val2 = (val2 * ch[j + ln][j]) % md;
                        ad(new long[]{dp2[0][i + ln][j + ln].second}, val2);

                        long val3 = (dp2[1][i][j].second * dp1[ln].first) % md;
                        val3 = (val3 * ch[j + ln][j]) % md;
                        ad(new long[]{dp2[0][i + ln][j + ln].second}, val3);
                    }
                }
            }
        }

        long an = 0;
        if (dp2[0][n][m] != null) {
            an = dp2[0][n][m].second;
        }
        if (dp2[1][n][m] != null) {
            an = (an + dp2[1][n][m].second) % md;
        }
        System.out.println(an);
        sc.close();
    }
}
